/* Italiano con Luke — reading comprehension passages. In each question the first option is correct. */
window.IT_READING = {
A1: [
{t:"A message from Marco",text:"Ciao Luke! Sono Marco. Stasera vado al cinema con Giulia. Il film comincia alle nove. Vieni con noi? Ci vediamo alle otto e mezza davanti al cinema Odeon, in via Roma. Dopo il film andiamo a mangiare una pizza. Rispondi presto! Marco",
q:[{q:"Where is Marco going tonight?",o:["To the cinema","To a restaurant only","To Giulia's house","To the station"],w:"Stasera vado al cinema."},{q:"What time does the film start?",o:["At 9:00","At 8:30","At 8:00","At 9:30"],w:"Il film comincia alle nove."},{q:"Where will they meet?",o:["In front of the Odeon cinema","At the pizzeria","In Piazza Roma","At Marco's house"],w:"Davanti al cinema Odeon, in via Roma."},{q:"What will they do after the film?",o:["Eat a pizza","Go home","Go to a bar","Watch another film"],w:"Dopo il film andiamo a mangiare una pizza."}]},
{t:"Hotel information",text:"Hotel Bellavista – Informazioni per gli ospiti. La colazione è servita dalle 7 alle 10 nella sala al primo piano. Il check-out è entro le 11. Il wi-fi è gratuito: la password è sulla chiave della camera. La reception è aperta 24 ore su 24. Il parcheggio costa 15 euro al giorno.",
q:[{q:"When is breakfast served?",o:["From 7 to 10","From 10 to 11","Until 11","All day"],w:"Dalle 7 alle 10."},{q:"Where is the wi-fi password?",o:["On the room key","At reception only","In the breakfast room","On the website"],w:"La password è sulla chiave della camera."},{q:"How much is parking?",o:["15 euros a day","Free","24 euros a day","15 euros a week"],w:"Il parcheggio costa 15 euro al giorno."},{q:"What time must guests check out?",o:["By 11","By 10","After 12","By 7"],w:"Il check-out è entro le 11."}]},
{t:"Giulia's family",text:"Mi chiamo Giulia e ho ventotto anni. Abito a Firenze con mio marito, Paolo. Paolo è ingegnere e lavora in un'azienda in centro. Io sono insegnante di inglese. I miei genitori abitano a Siena. Ho un fratello, Andrea, che studia medicina a Bologna. La domenica pranziamo tutti insieme dai miei genitori.",
q:[{q:"How old is Giulia?",o:["28","38","18","26"],w:"Ho ventotto anni."},{q:"What is Paolo's job?",o:["Engineer","English teacher","Doctor","Student"],w:"Paolo è ingegnere."},{q:"Where does Andrea study?",o:["Bologna","Siena","Florence","Rome"],w:"Studia medicina a Bologna."},{q:"What does the family do on Sundays?",o:["They have lunch at Giulia's parents'","They go to Bologna","They eat at a restaurant","They visit Paolo's office"],w:"La domenica pranziamo tutti insieme dai miei genitori."}]},
{t:"At the bakery",text:"Il forno di Nino è aperto dal lunedì al sabato, dalle 6:30 alle 13:00. La domenica è chiuso. Oggi ci sono pane fresco, pizza bianca e cornetti alla crema. Il pane costa 3 euro al chilo. La pizza bianca costa 1 euro e 50 al pezzo. Si accettano carte.",
q:[{q:"When is the bakery closed?",o:["On Sunday","On Monday","On Saturday afternoon only","Never"],w:"La domenica è chiuso."},{q:"How much is a kilo of bread?",o:["3 euros","1.50 euros","6.30 euros","13 euros"],w:"Il pane costa 3 euro al chilo."},{q:"Which of these is NOT mentioned?",o:["Ice cream","Fresh bread","Pizza bianca","Custard croissants"],w:"Only bread, pizza bianca and croissants are listed."},{q:"Can you pay by card?",o:["Yes","No, cash only","Only on Saturday","Only for bread"],w:"Si accettano carte."}]},
{t:"Luke's day",text:"Luke si sveglia alle sette. Fa la doccia e fa colazione al bar sotto casa: prende sempre un cappuccino e un cornetto. Alle otto e mezza prende l'autobus per andare a scuola di italiano. La lezione finisce all'una. Il pomeriggio Luke studia in biblioteca e la sera esce con gli amici.",
q:[{q:"Where does Luke have breakfast?",o:["At the café below his flat","At home","At school","At the library"],w:"Fa colazione al bar sotto casa."},{q:"How does he go to school?",o:["By bus","On foot","By train","By bike"],w:"Prende l'autobus."},{q:"When does the lesson finish?",o:["At 1 pm","At 8:30","At 7","In the evening"],w:"La lezione finisce all'una."},{q:"What does Luke do in the afternoon?",o:["He studies in the library","He goes out with friends","He sleeps","He works in a café"],w:"Il pomeriggio studia in biblioteca."}]},
{t:"Apartment for rent",text:"Affittasi appartamento a Roma, zona Trastevere. Due camere da letto, un bagno, cucina e soggiorno. Terzo piano con ascensore. Vicino all'autobus e ai negozi. 1.200 euro al mese, spese incluse. Non sono ammessi animali. Telefonare a Laura dopo le 18.",
q:[{q:"How many bedrooms does the flat have?",o:["Two","One","Three","Four"],w:"Due camere da letto."},{q:"Which floor is it on?",o:["The third","The ground floor","The first","The second"],w:"Terzo piano con ascensore."},{q:"Are pets allowed?",o:["No","Yes","Only cats","Only small dogs"],w:"Non sono ammessi animali."},{q:"When should you call Laura?",o:["After 6 pm","Before 6 pm","In the morning","At lunchtime"],w:"Telefonare dopo le 18."}]},
{t:"Weather forecast",text:"Previsioni per domani. Al nord: nuvole e pioggia, temperature tra 8 e 12 gradi. Al centro: sole la mattina e nuvole il pomeriggio, temperature tra 14 e 18 gradi. Al sud e nelle isole: sole e caldo, fino a 24 gradi. Vento forte in Sardegna.",
q:[{q:"What will the weather be like in the north?",o:["Cloudy and rainy","Sunny and hot","Windy and sunny","Snowy"],w:"Al nord: nuvole e pioggia."},{q:"Where will it be hottest?",o:["In the south and islands","In the north","In the centre","Everywhere the same"],w:"Al sud e nelle isole: fino a 24 gradi."},{q:"What about the centre in the afternoon?",o:["Cloudy","Rainy","Very windy","Sunny"],w:"Nuvole il pomeriggio."},{q:"Where will there be strong wind?",o:["Sardinia","Sicily","The north","Rome"],w:"Vento forte in Sardegna."}]},
{t:"A postcard from Venice",text:"Cara mamma, sono a Venezia con Giulia. La città è bellissima! Ieri abbiamo fatto un giro in gondola e oggi visitiamo il Palazzo Ducale. L'albergo è piccolo ma molto carino, vicino a piazza San Marco. Fa freddo, ma c'è il sole. Torno a casa venerdì. Un abbraccio, Luke",
q:[{q:"Who is Luke writing to?",o:["His mother","Giulia","A hotel","His teacher"],w:"Cara mamma."},{q:"What did they do yesterday?",o:["A gondola ride","Visited the Doge's Palace","Went home","Stayed at the hotel"],w:"Ieri abbiamo fatto un giro in gondola."},{q:"How is the weather?",o:["Cold but sunny","Hot and sunny","Rainy","Foggy"],w:"Fa freddo, ma c'è il sole."},{q:"When is Luke going home?",o:["On Friday","Today","Tomorrow","On Sunday"],w:"Torno a casa venerdì."}]},
{t:"Museum opening times",text:"Museo Civico d'Arte. Orari: dal martedì alla domenica, dalle 9 alle 19. Lunedì chiuso. Prenotazione obbligatoria. Biglietto intero: 15 euro. Ridotto (18-25 anni): 2 euro. Gratis per i minori di 18 anni. La prima domenica del mese l'ingresso è gratuito per tutti.",
q:[{q:"On which day is the gallery closed?",o:["Monday","Sunday","Tuesday","Saturday"],w:"Lunedì chiuso."},{q:"Is booking necessary?",o:["Yes, it's compulsory","No","Only on Sundays","Only for groups"],w:"Prenotazione obbligatoria."},{q:"How much does a 20-year-old pay?",o:["2 euros","15 euros","Nothing","19 euros"],w:"Ridotto (18-25 anni): 2 euro."},{q:"When is entry free for everyone?",o:["The first Sunday of the month","Every Sunday","Every Monday","In the evening"],w:"La prima domenica del mese l'ingresso è gratuito."}]},
{t:"Shopping list",text:"Lista della spesa per la cena di sabato: un chilo di pomodori, due mozzarelle, un pacco di spaghetti, basilico, olio d'oliva, sei uova e una bottiglia di vino rosso. Per il dolce: mascarpone, biscotti savoiardi e caffè. Non dimenticare il pane!",
q:[{q:"When is the dinner?",o:["On Saturday","On Sunday","Tonight","On Friday"],w:"La cena di sabato."},{q:"How many eggs are needed?",o:["Six","Two","One","Twelve"],w:"Sei uova."},{q:"What kind of wine?",o:["Red","White","Sparkling","Rosé"],w:"Una bottiglia di vino rosso."},{q:"Which dessert are they probably making?",o:["Tiramisù","Panna cotta","Cannoli","Gelato"],w:"Mascarpone, savoiardi and coffee are the ingredients of tiramisù."}]},
{t:"Train announcement",text:"Attenzione. Il treno regionale 2145 delle ore 10:15 per Pisa Centrale partirà dal binario 7 invece che dal binario 3. Il treno ha un ritardo di 10 minuti. Ferma a Empoli e Pontedera. Ci scusiamo per il disagio.",
q:[{q:"Where is the train going?",o:["Pisa","Empoli","Florence","Pontedera only"],w:"Per Pisa Centrale."},{q:"Which platform will it leave from?",o:["Platform 7","Platform 3","Platform 10","Platform 2"],w:"Dal binario 7 invece che dal binario 3."},{q:"How late is the train?",o:["10 minutes","15 minutes","7 minutes","It's on time"],w:"Un ritardo di 10 minuti."},{q:"Where does it stop?",o:["Empoli and Pontedera","Only Empoli","Florence and Pisa only","It doesn't stop"],w:"Ferma a Empoli e Pontedera."}]},
{t:"Sara introduces herself",text:"Ciao a tutti! Mi chiamo Sara, sono di Napoli ma abito a Milano da due anni. Lavoro in un negozio di vestiti. Nel tempo libero mi piace cucinare e ballare. Non mi piace il freddo di Milano! Ho un gatto, si chiama Pippo. Cerco amici per fare conversazione in inglese.",
q:[{q:"Where is Sara from?",o:["Naples","Milan","Rome","Turin"],w:"Sono di Napoli."},{q:"Where does she work?",o:["In a clothes shop","In a restaurant","In a school","At home"],w:"Lavoro in un negozio di vestiti."},{q:"What doesn't she like?",o:["The cold in Milan","Cooking","Dancing","Her cat"],w:"Non mi piace il freddo di Milano."},{q:"What is she looking for?",o:["Friends to practise English with","A new job","A flat","A cat"],w:"Cerco amici per fare conversazione in inglese."}]},
{t:"Restaurant menu",text:"Trattoria da Rosa – Menù del giorno: 14 euro. Primo: lasagne alla bolognese oppure minestrone. Secondo: pollo arrosto con patate oppure pesce del giorno. Acqua e caffè compresi. Il vino non è compreso. Disponibile solo a pranzo, dal lunedì al venerdì.",
q:[{q:"How much is the menu of the day?",o:["14 euros","4 euros","10 euros","It varies"],w:"Menù del giorno: 14 euro."},{q:"What is included?",o:["Water and coffee","Wine","Dessert","Bread and wine"],w:"Acqua e caffè compresi."},{q:"Which is a first course option?",o:["Minestrone","Roast chicken","Fish of the day","Potatoes"],w:"Primo: lasagne oppure minestrone."},{q:"When is the menu available?",o:["Weekday lunchtimes","Every evening","At weekends","All day every day"],w:"Solo a pranzo, dal lunedì al venerdì."}]}
],
A2: [
{t:"A weekend in Florence",text:"Lo scorso fine settimana Luke e Giulia sono andati a Firenze. Sono partiti sabato mattina con il treno delle otto e sono arrivati verso le dieci. Hanno lasciato le valigie in albergo e sono andati subito agli Uffizi, perché avevano prenotato i biglietti. Il pomeriggio hanno passeggiato sul Ponte Vecchio, ma c'era troppa gente. La sera hanno mangiato una bistecca alla fiorentina in una trattoria. Domenica pioveva, così sono rimasti in un caffè a leggere e sono tornati a Roma nel pomeriggio.",
q:[{q:"Why did they go straight to the Uffizi?",o:["They had booked tickets","It was raining","The hotel was closed","It was free on Saturday"],w:"Perché avevano prenotato i biglietti."},{q:"What was the problem on the Ponte Vecchio?",o:["It was too crowded","It was closed","It was raining","They got lost"],w:"C'era troppa gente."},{q:"What did they do on Sunday?",o:["Stayed in a café reading","Visited more museums","Went to the beach","Went shopping"],w:"Sono rimasti in un caffè a leggere."},{q:"When did they go back to Rome?",o:["On Sunday afternoon","On Saturday evening","On Monday morning","On Sunday morning"],w:"Sono tornati a Roma nel pomeriggio (domenica)."}]},
{t:"Email to a landlord",text:"Gentile signora Ferri, le scrivo perché da tre giorni la lavatrice non funziona. Ho provato a spegnerla e riaccenderla, ma non parte. Inoltre, il rubinetto della cucina perde acqua. Potrebbe mandare un tecnico questa settimana? Io sono a casa tutti i pomeriggi dopo le quattro. Grazie mille, cordiali saluti, Luke Bennett",
q:[{q:"What is broken?",o:["The washing machine","The fridge","The oven","The heating"],w:"La lavatrice non funziona."},{q:"What other problem is mentioned?",o:["The kitchen tap is leaking","The door doesn't close","The lights don't work","The window is broken"],w:"Il rubinetto della cucina perde acqua."},{q:"What does Luke ask for?",o:["A technician this week","A new flat","A refund","To pay less rent"],w:"Potrebbe mandare un tecnico questa settimana?"},{q:"When is Luke at home?",o:["Every afternoon after four","Every morning","Only at weekends","Never"],w:"Tutti i pomeriggi dopo le quattro."}]},
{t:"The Italian bar",text:"In Italia il bar non è solo un posto dove si beve alcol: è il luogo dove gli italiani fanno colazione, bevono il caffè durante la pausa e si incontrano con gli amici. Molti italiani bevono il caffè in piedi al banco, perché costa meno e si fa in fretta. Se ti siedi al tavolo, spesso paghi di più. Il cappuccino si beve solo la mattina: ordinarlo dopo pranzo è considerato strano.",
q:[{q:"According to the text, the Italian bar is:",o:["a place for coffee, breakfast and meeting friends","only a place for alcohol","a restaurant","a night club"],w:"Non è solo un posto dove si beve alcol."},{q:"Why do many Italians drink coffee standing?",o:["It's cheaper and quicker","Tables are forbidden","It's healthier","Bars have no chairs"],w:"Costa meno e si fa in fretta."},{q:"What happens if you sit at a table?",o:["You often pay more","You pay less","You must order food","You can't drink coffee"],w:"Spesso paghi di più."},{q:"When is cappuccino usually drunk?",o:["In the morning","After lunch","In the evening","With dinner"],w:"Il cappuccino si beve solo la mattina."}]},
{t:"Childhood memories",text:"Quando ero bambina abitavo in un piccolo paese in Puglia. D'estate andavo al mare tutti i giorni con mia nonna. Lei preparava sempre dei panini enormi con pomodoro e mozzarella. Il pomeriggio, quando faceva troppo caldo, dormivamo e poi giocavamo in piazza fino a sera. Una volta, a dieci anni, mi sono persa nel mercato e mio padre mi ha cercata per un'ora!",
q:[{q:"Where did the writer live as a child?",o:["In a small village in Puglia","In Rome","In a big city","By the mountains"],w:"In un piccolo paese in Puglia."},{q:"Who did she go to the beach with?",o:["Her grandmother","Her father","Her friends","Alone"],w:"Con mia nonna."},{q:"What did they do in the hot afternoons?",o:["They slept","They swam","They went to the market","They cooked"],w:"Dormivamo."},{q:"What happened once when she was ten?",o:["She got lost at the market","She broke her arm","She won a prize","She moved to the city"],w:"Mi sono persa nel mercato."}]},
{t:"Car sharing in Milan",text:"A Milano sempre più persone usano il car sharing. Funziona così: scarichi un'app, trovi l'auto più vicina sulla mappa e la apri con il telefono. Paghi solo i minuti che usi. Puoi lasciare la macchina in qualsiasi parcheggio pubblico della città, anche nelle zone a traffico limitato. È comodo per chi non ha l'auto, ma nelle ore di punta può essere difficile trovarne una libera.",
q:[{q:"How do you open the car?",o:["With your phone","With a key from an office","With a card from the bank","You don't need to open it"],w:"La apri con il telefono."},{q:"What do you pay for?",o:["Only the minutes you use","A monthly fee only","A daily rate","Petrol only"],w:"Paghi solo i minuti che usi."},{q:"Where can you leave the car?",o:["In any public car park in the city","Only at the station","Only outside the centre","Only at home"],w:"In qualsiasi parcheggio pubblico."},{q:"What is the disadvantage mentioned?",o:["It's hard to find a free car at rush hour","It's very expensive","It's only for tourists","The app doesn't work"],w:"Nelle ore di punta può essere difficile trovarne una libera."}]},
{t:"At the doctor's",text:"Dottore: Buongiorno, cosa si sente? Paziente: Da ieri ho la febbre a 38 e mi fa male la gola. Dottore: Ha anche la tosse? Paziente: Sì, soprattutto di notte. Dottore: Probabilmente è un'influenza. Le prescrivo uno sciroppo per la tosse. Beva molta acqua e resti a casa per tre giorni. Se tra tre giorni la febbre non passa, torni da me.",
q:[{q:"Since when has the patient had a fever?",o:["Since yesterday","For three days","For a week","Since this morning"],w:"Da ieri ho la febbre."},{q:"When is the cough worse?",o:["At night","In the morning","After eating","When walking"],w:"Soprattutto di notte."},{q:"What does the doctor prescribe?",o:["A cough syrup","Antibiotics","An injection","Nothing"],w:"Uno sciroppo per la tosse."},{q:"What should the patient do if the fever continues?",o:["Go back to the doctor","Go to hospital immediately","Take more syrup","Go to work"],w:"Torni da me."}]},
{t:"Festival in Siena",text:"Il Palio di Siena è una corsa di cavalli che si svolge due volte all'anno, il 2 luglio e il 16 agosto, in Piazza del Campo. Partecipano dieci delle diciassette contrade, cioè i quartieri della città. La corsa dura circa novanta secondi, ma la festa comincia giorni prima, con cene in strada e cortei in costume medievale. Per i senesi il Palio non è uno spettacolo per turisti: è una passione che dura tutto l'anno.",
q:[{q:"How often is the Palio held?",o:["Twice a year","Once a year","Every month","Every four years"],w:"Due volte all'anno."},{q:"How many contrade take part in each race?",o:["Ten","Seventeen","Two","Ninety"],w:"Partecipano dieci delle diciassette contrade."},{q:"How long does the race last?",o:["About ninety seconds","About ninety minutes","A whole day","Ten minutes"],w:"Circa novanta secondi."},{q:"For the Sienese, the Palio is:",o:["a year-round passion","a show for tourists","a modern invention","a quiet religious event"],w:"Una passione che dura tutto l'anno."}]},
{t:"Job advert",text:"Cercasi cameriere/a per ristorante nel centro di Bologna. Richiesta esperienza di almeno un anno e conoscenza dell'inglese. Orario: dal martedì alla domenica, dalle 18 alle 24. Lunedì libero. Offriamo contratto regolare e pasto incluso. Inviare il curriculum entro il 15 maggio a lavoro@ristorantelatorre.it",
q:[{q:"What job is being offered?",o:["Waiter/waitress","Cook","Manager","Cleaner"],w:"Cercasi cameriere/a."},{q:"What is required?",o:["At least one year's experience and English","A university degree","A driving licence","French and German"],w:"Esperienza di almeno un anno e conoscenza dell'inglese."},{q:"Which day is free?",o:["Monday","Sunday","Tuesday","Saturday"],w:"Lunedì libero."},{q:"What is the deadline?",o:["15 May","24 May","The end of May","There is no deadline"],w:"Entro il 15 maggio."}]},
{t:"Moving to Italy",text:"Mi chiamo Emma e sono inglese. Sei mesi fa mi sono trasferita a Torino per lavoro. All'inizio è stato difficile: non capivo quasi niente e la burocrazia mi sembrava impossibile. Adesso va molto meglio: ho seguito un corso di italiano, ho conosciuto i miei vicini e ho trovato una squadra di pallavolo. Quello che mi manca di più dell'Inghilterra? Il tè! Qui tutti bevono caffè.",
q:[{q:"Why did Emma move to Turin?",o:["For work","To study","To get married","For a holiday"],w:"Per lavoro."},{q:"What was difficult at the beginning?",o:["Understanding people and bureaucracy","Finding a flat","The food","The weather"],w:"Non capivo quasi niente e la burocrazia mi sembrava impossibile."},{q:"Which activity has she found?",o:["A volleyball team","A choir","A cooking class","A football team"],w:"Una squadra di pallavolo."},{q:"What does she miss most?",o:["Tea","Her family","English weather","English food in general"],w:"Il tè!"}]},
{t:"Instructions for guests",text:"Benvenuti nella nostra casa vacanze! Le chiavi sono nella cassetta vicino alla porta: il codice è 4821. Per favore, fate la raccolta differenziata: carta il lunedì, plastica il mercoledì, organico il martedì e il venerdì. Non lasciate i sacchi fuori la sera prima. Il giorno della partenza lasciate le chiavi sul tavolo della cucina. Buona vacanza!",
q:[{q:"Where are the keys?",o:["In the box near the door","Under the mat","With a neighbour","At a bar"],w:"Nella cassetta vicino alla porta."},{q:"When is paper collected?",o:["Monday","Wednesday","Tuesday and Friday","Every day"],w:"Carta il lunedì."},{q:"What should guests NOT do?",o:["Leave bags outside the night before","Recycle","Use the code","Use the kitchen"],w:"Non lasciate i sacchi fuori la sera prima."},{q:"Where should the keys be left on departure?",o:["On the kitchen table","In the box","At the station","In the mailbox"],w:"Sul tavolo della cucina."}]},
{t:"A review",text:"Siamo stati in questo agriturismo per una settimana ad agosto. La posizione è fantastica, tra le colline del Chianti, e la piscina è molto pulita. La colazione era abbondante, con torte fatte in casa. L'unico problema: il wi-fi funzionava solo nella sala comune. I proprietari sono gentilissimi e ci hanno anche organizzato una degustazione di vini. Torneremo sicuramente!",
q:[{q:"How long did they stay?",o:["One week","One night","Two weeks","A month"],w:"Per una settimana."},{q:"What was the only problem?",o:["The wi-fi only worked in the common room","The pool was dirty","The owners were rude","Breakfast was small"],w:"Il wi-fi funzionava solo nella sala comune."},{q:"What did the owners organise?",o:["A wine tasting","A cooking class","A trip to Florence","A party"],w:"Una degustazione di vini."},{q:"Will they go back?",o:["Yes, definitely","No","Maybe","Only in winter"],w:"Torneremo sicuramente!"}]},
{t:"Lost and found",text:"Ieri sera ho perso il mio zaino sull'autobus 64, tra la stazione Termini e San Pietro. È uno zaino blu con dentro un computer portatile, un libro di italiano e un ombrello nero. Chi lo trova può chiamarmi al numero 347 123 4567. Offro una ricompensa. Grazie! Luke",
q:[{q:"Where did Luke lose his backpack?",o:["On bus 64","At Termini station","At St Peter's","In a café"],w:"Sull'autobus 64."},{q:"What colour is the backpack?",o:["Blue","Black","Red","Green"],w:"Uno zaino blu."},{q:"Which object is NOT in the backpack?",o:["A wallet","A laptop","An Italian book","An umbrella"],w:"The wallet isn't mentioned."},{q:"What does Luke offer?",o:["A reward","A new backpack","A dinner","Nothing"],w:"Offro una ricompensa."}]},
{t:"Gym timetable",text:"Palestra Energia – Corsi della settimana. Yoga: lunedì e giovedì alle 19. Pilates: martedì alle 18:30. Spinning: mercoledì e venerdì alle 7 di mattina e alle 20. Il sabato la palestra chiude alle 14. La domenica è chiusa. Per i corsi è necessario prenotare il giorno prima tramite l'app.",
q:[{q:"When is yoga?",o:["Monday and Thursday at 7 pm","Tuesday at 6:30 pm","Wednesday at 7 am","Saturday morning"],w:"Yoga: lunedì e giovedì alle 19."},{q:"What time does the gym close on Saturday?",o:["2 pm","7 pm","8 pm","It's closed all day"],w:"Il sabato la palestra chiude alle 14."},{q:"How do you book a class?",o:["Via the app, the day before","By phone on the day","At reception only","You don't need to book"],w:"Prenotare il giorno prima tramite l'app."},{q:"Which class is available early in the morning?",o:["Spinning","Yoga","Pilates","None"],w:"Spinning alle 7 di mattina."}]}
],
B1: [
{t:"Slow Food",text:"Il movimento Slow Food è nato in Piemonte nel 1986, quando un gruppo di giornalisti e gastronomi decise di protestare contro l'apertura di un fast food vicino a Piazza di Spagna, a Roma. L'idea era semplice: il cibo deve essere 'buono, pulito e giusto', cioè gustoso, prodotto senza danneggiare l'ambiente e pagato il giusto a chi lo produce. Oggi Slow Food è presente in oltre 160 paesi e sostiene i piccoli produttori locali attraverso progetti come i Presìdi, che proteggono prodotti tradizionali a rischio di scomparire.",
q:[{q:"What triggered the birth of Slow Food?",o:["A fast food opening in Rome","A food festival in Piedmont","A new law on agriculture","A restaurant closing"],w:"Protestare contro l'apertura di un fast food."},{q:"What does 'giusto' mean in the motto?",o:["Fairly paid to producers","Healthy","Cheap","Fast"],w:"Pagato il giusto a chi lo produce."},{q:"What are the Presìdi?",o:["Projects protecting traditional products at risk","Restaurants run by the movement","Food laws","Cooking schools"],w:"Proteggono prodotti tradizionali a rischio di scomparire."},{q:"Where was the movement founded?",o:["In Piedmont","In Rome","In Tuscany","Abroad"],w:"È nato in Piemonte."}]},
{t:"Smart working",text:"Dopo la pandemia, molte aziende italiane hanno mantenuto lo smart working, almeno per alcuni giorni alla settimana. Secondo un recente sondaggio, il 60% dei lavoratori preferisce un modello ibrido: due o tre giorni a casa e il resto in ufficio. I vantaggi sono evidenti: si risparmia tempo negli spostamenti e si concilia meglio il lavoro con la vita privata. Tuttavia, alcuni lamentano l'isolamento e la difficoltà di separare gli orari di lavoro dal tempo libero. Per questo diverse aziende hanno introdotto il 'diritto alla disconnessione'.",
q:[{q:"What do most workers prefer according to the survey?",o:["A hybrid model","Working only from home","Working only in the office","Part-time work"],w:"Il 60% preferisce un modello ibrido."},{q:"Which advantage is mentioned?",o:["Saving commuting time","Higher salaries","More holidays","Better offices"],w:"Si risparmia tempo negli spostamenti."},{q:"Which disadvantage is mentioned?",o:["Isolation","Lower productivity","Expensive equipment","Longer commutes"],w:"Alcuni lamentano l'isolamento."},{q:"What is the 'diritto alla disconnessione'?",o:["The right not to be contacted outside working hours","The right to work from abroad","A ban on computers","Free internet at home"],w:"It addresses separating work hours from free time."}]},
{t:"A difficult choice",text:"Cara Laura, ti scrivo perché ho bisogno di un consiglio. Mi hanno offerto un lavoro a Milano: lo stipendio è più alto e l'azienda è molto famosa. Però dovrei lasciare Napoli, la mia famiglia e i miei amici. Mia madre dice che sono pazzo a rifiutare, mentre la mia ragazza teme che la nostra relazione non sopravviva alla distanza. Io non so cosa fare: da un lato voglio crescere professionalmente, dall'altro ho paura di sentirmi solo. Tu cosa faresti al posto mio? Un abbraccio, Davide",
q:[{q:"Why is Davide writing?",o:["To ask for advice","To announce a wedding","To complain about his job","To invite Laura to Milan"],w:"Ho bisogno di un consiglio."},{q:"What does his mother think?",o:["He'd be crazy to refuse","He should stay in Naples","He should ask his girlfriend","He should study more"],w:"Dice che sono pazzo a rifiutare."},{q:"What does his girlfriend fear?",o:["Their relationship won't survive the distance","He'll earn too little","Milan is dangerous","He'll lose his job"],w:"Teme che la nostra relazione non sopravviva alla distanza."},{q:"What is Davide afraid of?",o:["Feeling lonely","Earning less","The company's reputation","The weather in Milan"],w:"Ho paura di sentirmi solo."}]},
{t:"Venice and tourism",text:"Ogni anno Venezia accoglie circa venti milioni di visitatori, mentre i residenti del centro storico sono scesi sotto i 50.000. Molti veneziani si sono trasferiti in terraferma perché gli affitti sono troppo alti e molti appartamenti sono diventati case vacanza. Per limitare il turismo di giornata, il Comune ha introdotto un contributo d'accesso nei giorni di maggiore affluenza. I critici sostengono che la misura non basti e che serva una politica per riportare gli abitanti in città.",
q:[{q:"Why have many Venetians moved to the mainland?",o:["Rents are too high","There's no work in Venice","The schools closed","Because of flooding only"],w:"Gli affitti sono troppo alti."},{q:"What happened to many flats?",o:["They became holiday homes","They were demolished","They became offices","They were sold to the city"],w:"Sono diventati case vacanza."},{q:"What is the 'contributo d'accesso' meant to limit?",o:["Day-trip tourism","Hotel prices","Boat traffic","Residents' cars"],w:"Per limitare il turismo di giornata."},{q:"What do critics say?",o:["The measure isn't enough","The measure is too strict","Tourism should increase","Residents should leave"],w:"La misura non basti."}]},
{t:"The Mediterranean diet",text:"Nel 2010 l'UNESCO ha riconosciuto la dieta mediterranea come patrimonio culturale immateriale dell'umanità. Non si tratta solo di un elenco di alimenti — olio d'oliva, cereali, legumi, verdura, frutta e pesce — ma di uno stile di vita che comprende la convivialità, la stagionalità e il rispetto per il territorio. Il nutrizionista americano Ancel Keys, che negli anni Cinquanta studiò le abitudini alimentari del Cilento, fu tra i primi a collegare questo modello alimentare a una minore incidenza di malattie cardiovascolari.",
q:[{q:"What did UNESCO do in 2010?",o:["Recognised the Mediterranean diet as intangible heritage","Banned fast food","Created a cooking school","Published a recipe book"],w:"Ha riconosciuto la dieta mediterranea come patrimonio."},{q:"According to the text, the Mediterranean diet is:",o:["a lifestyle, not just a list of foods","only about olive oil","a modern invention","a weight-loss programme"],w:"Non si tratta solo di un elenco di alimenti ma di uno stile di vita."},{q:"Who was Ancel Keys?",o:["An American nutritionist","An Italian chef","A UNESCO director","A farmer from Cilento"],w:"Il nutrizionista americano Ancel Keys."},{q:"What did he link the diet to?",o:["Fewer cardiovascular diseases","Longer working hours","Higher intelligence","Better sleep"],w:"Minore incidenza di malattie cardiovascolari."}]},
{t:"Learning Italian online",text:"Negli ultimi anni il numero di persone che studiano italiano nel mondo è cresciuto, soprattutto grazie alle app e ai corsi online. L'italiano è spesso tra le lingue più studiate, anche se non è tra le più parlate. Perché? Molti studenti dicono di essere attratti dalla cultura: la musica lirica, l'arte, il cinema, il design e naturalmente la cucina. Altri lo studiano per motivi familiari, perché hanno origini italiane. Gli insegnanti però avvertono: le app sono utili, ma non sostituiscono la conversazione con persone vere.",
q:[{q:"What has helped the growth of Italian learners?",o:["Apps and online courses","New laws","Cheaper flights only","Italian TV abroad"],w:"Grazie alle app e ai corsi online."},{q:"Why do many students choose Italian?",o:["They are attracted by the culture","It's the most spoken language","It's required at school","It's very easy"],w:"Attratti dalla cultura."},{q:"Another reason mentioned is:",o:["Family origins","Business only","Military service","Sport"],w:"Hanno origini italiane."},{q:"What do teachers warn about?",o:["Apps don't replace real conversation","Apps are useless","Grammar is unnecessary","Online courses are too expensive"],w:"Non sostituiscono la conversazione con persone vere."}]},
{t:"A complaint",text:"Gentile Servizio Clienti, il 3 marzo ho acquistato sul vostro sito un paio di scarpe da trekking (ordine n. 45821). Il pacco è arrivato con una settimana di ritardo e, quando l'ho aperto, ho visto che le scarpe erano di due numeri diversi: il destro 42 e il sinistro 43. Ho già provato a chiamare il numero verde tre volte, ma nessuno ha risposto. Vi chiedo di sostituire il prodotto al più presto o, in alternativa, di rimborsarmi l'intero importo. Distinti saluti, Luke Bennett",
q:[{q:"What did Luke buy?",o:["Hiking shoes","A jacket","A backpack","Running shoes"],w:"Scarpe da trekking."},{q:"What was wrong with them?",o:["They were two different sizes","They were the wrong colour","They were broken","They were too expensive"],w:"Il destro 42 e il sinistro 43."},{q:"What happened when he called customer service?",o:["Nobody answered","They promised a refund","They were rude","They sent new shoes"],w:"Nessuno ha risposto."},{q:"What does Luke ask for?",o:["A replacement or a full refund","A discount on the next order","A letter of apology only","Free delivery"],w:"Sostituire il prodotto o rimborsare l'intero importo."}]},
{t:"The Italian 'aperitivo'",text:"L'aperitivo è un rito tipicamente italiano, nato a Torino alla fine del Settecento con l'invenzione del vermut. Oggi si beve tra le sei e le otto di sera, prima di cena, per 'aprire lo stomaco'. A Milano è diventato un vero fenomeno sociale: con un drink si può spesso accedere a un buffet di stuzzichini, pasta fredda e verdure, tanto che per molti giovani l'aperitivo sostituisce la cena. I drink più famosi sono lo Spritz, il Negroni e l'Americano.",
q:[{q:"Where was the aperitivo born?",o:["Turin","Milan","Venice","Rome"],w:"Nato a Torino."},{q:"When is it usually drunk?",o:["Between 6 and 8 pm","After dinner","At lunchtime","Late at night"],w:"Tra le sei e le otto di sera."},{q:"What is typical of the Milanese aperitivo?",o:["A buffet included with the drink","Free wine for everyone","It's only for tourists","It starts at midnight"],w:"Con un drink si può accedere a un buffet."},{q:"For many young people, the aperitivo:",o:["replaces dinner","replaces breakfast","is too expensive","is forbidden"],w:"Per molti giovani l'aperitivo sostituisce la cena."}]},
{t:"Volunteering",text:"Ogni sabato mattina Chiara, una studentessa di 22 anni, fa volontariato in una mensa per persone senza dimora a Bologna. 'All'inizio pensavo di non avere tempo,' racconta, 'ma poi ho capito che bastano poche ore per fare la differenza.' Chiara serve i pasti, ma soprattutto parla con le persone. 'Molti hanno bisogno di qualcuno che li ascolti più che di un piatto di pasta.' Grazie a questa esperienza, Chiara ha deciso di iscriversi a un master in servizi sociali.",
q:[{q:"Where does Chiara volunteer?",o:["In a soup kitchen for homeless people","In a hospital","In a school","In an animal shelter"],w:"In una mensa per persone senza dimora."},{q:"What did she think at first?",o:["That she didn't have time","That it would be boring","That it was dangerous","That she'd be paid"],w:"Pensavo di non avere tempo."},{q:"According to Chiara, many people need above all:",o:["someone to listen to them","more food","money","a job"],w:"Hanno bisogno di qualcuno che li ascolti."},{q:"What did the experience lead her to do?",o:["Enrol in a master's in social services","Open a restaurant","Leave Bologna","Stop studying"],w:"Ha deciso di iscriversi a un master in servizi sociali."}]},
{t:"Trains in Italy",text:"Negli ultimi vent'anni l'alta velocità ha cambiato il modo di viaggiare in Italia. Oggi da Roma a Milano ci vogliono circa tre ore, contro le sei o sette di una volta, e molti professionisti preferiscono il treno all'aereo. Due compagnie, Trenitalia e Italo, si fanno concorrenza su queste tratte, e questo ha fatto scendere i prezzi. Il problema resta il Sud: in molte zone della Sicilia e della Calabria i treni sono ancora lenti e poco frequenti.",
q:[{q:"How long does Rome–Milan take today by high-speed train?",o:["About three hours","Six or seven hours","One hour","Five hours"],w:"Circa tre ore."},{q:"Why have prices dropped?",o:["Two companies compete","The government pays for tickets","Fewer people travel","Trains are slower"],w:"Due compagnie si fanno concorrenza."},{q:"What do many professionals prefer?",o:["The train to the plane","The car to the train","The bus","Flying"],w:"Preferiscono il treno all'aereo."},{q:"What problem remains?",o:["Slow, infrequent trains in parts of the South","High prices in the North","Too many trains in Milan","No trains to Rome"],w:"Il problema resta il Sud."}]},
{t:"The 'nonni' in Italian families",text:"In Italia i nonni hanno un ruolo fondamentale nella vita familiare. Secondo l'ISTAT, milioni di nonni si occupano regolarmente dei nipoti mentre i genitori lavorano. Senza di loro, molte famiglie non riuscirebbero a conciliare lavoro e figli, anche perché gli asili nido pubblici sono pochi e spesso costosi. Questo legame tra generazioni ha anche un valore affettivo: i bambini imparano dai nonni ricette, dialetti e storie del passato.",
q:[{q:"What do many grandparents do?",o:["Look after their grandchildren","Work full time","Live abroad","Run nurseries"],w:"Si occupano regolarmente dei nipoti."},{q:"Why are grandparents so important for working parents?",o:["Public nurseries are few and costly","Parents don't like nurseries","Schools are closed","Grandparents pay salaries"],w:"Gli asili nido pubblici sono pochi e spesso costosi."},{q:"What is ISTAT?",o:["A source of statistics","A nursery","A family law","A dialect"],w:"Secondo l'ISTAT — the national statistics institute."},{q:"What do children learn from grandparents?",o:["Recipes, dialects and stories","Foreign languages","Computer skills","Sports"],w:"Ricette, dialetti e storie del passato."}]},
{t:"A new library",text:"La nuova biblioteca comunale aprirà il 1° settembre nell'ex stazione ferroviaria, ristrutturata grazie ai fondi europei. Oltre ai libri, offrirà una sala studio aperta fino a mezzanotte, spazi per bambini, corsi di lingua gratuiti e una caffetteria. Il sindaco ha dichiarato che l'obiettivo è trasformare la biblioteca in una 'piazza coperta', un luogo d'incontro per tutte le età. Per iscriversi basterà presentare un documento d'identità.",
q:[{q:"Where will the new library be?",o:["In the former railway station","In the town hall","In a school","In a new skyscraper"],w:"Nell'ex stazione ferroviaria."},{q:"How was the renovation funded?",o:["With European funds","By private donors","By selling books","By the library users"],w:"Grazie ai fondi europei."},{q:"Until when will the study room be open?",o:["Midnight","8 pm","6 pm","24 hours"],w:"Sala studio aperta fino a mezzanotte."},{q:"What does the mayor mean by 'piazza coperta'?",o:["A meeting place for all ages","A covered market","A car park","A sports hall"],w:"Un luogo d'incontro per tutte le età."}]},
{t:"Cycling holidays",text:"Il cicloturismo è sempre più popolare in Italia. Percorsi come la ciclovia del Po o la pista ciclabile delle Dolomiti attirano ogni anno migliaia di appassionati, anche stranieri. Molti alberghi offrono servizi dedicati: deposito sicuro per le bici, officina e trasporto bagagli da una tappa all'altra. Con le biciclette elettriche, poi, anche chi non è allenato può affrontare salite impegnative. Secondo gli esperti, questo tipo di turismo aiuta i piccoli borghi, lontani dalle mete più famose.",
q:[{q:"What is 'cicloturismo'?",o:["Cycling holidays","Bike racing","Bike manufacturing","Cycling to work"],w:"Turismo in bicicletta."},{q:"Which hotel service is mentioned?",o:["Luggage transport between stages","Free bikes for everyone","Cycling lessons","Discounted meals"],w:"Trasporto bagagli da una tappa all'altra."},{q:"What makes steep climbs possible for untrained people?",o:["Electric bikes","Better roads","Shorter routes","Group tours"],w:"Con le biciclette elettriche."},{q:"According to experts, this tourism helps:",o:["small villages away from famous destinations","big cities","car manufacturers","airlines"],w:"Aiuta i piccoli borghi."}]}
],
B2: [
{t:"The brain drain",text:"La cosiddetta 'fuga dei cervelli' è uno dei temi più discussi del dibattito pubblico italiano. Ogni anno decine di migliaia di giovani laureati lasciano il Paese in cerca di stipendi più alti, contratti stabili e maggiori opportunità di carriera, soprattutto nella ricerca. Se da un lato l'esperienza all'estero può arricchire chi parte, dall'altro l'Italia perde il ritorno dell'investimento fatto nella loro formazione. Negli ultimi anni il governo ha introdotto agevolazioni fiscali per chi rientra, ma secondo molti osservatori il problema è strutturale: finché il mercato del lavoro non premierà il merito, gli incentivi resteranno un palliativo.",
q:[{q:"Why do many young graduates leave Italy?",o:["Better pay, stable contracts and career opportunities","Lower taxes only","Cheaper housing","To learn languages"],w:"In cerca di stipendi più alti, contratti stabili e opportunità."},{q:"What does Italy lose, according to the text?",o:["The return on its investment in their education","Its universities","Tourists","Foreign investors"],w:"Perde il ritorno dell'investimento fatto nella loro formazione."},{q:"What has the government introduced?",o:["Tax breaks for those who return","A ban on emigration","Free university","Higher salaries for everyone"],w:"Agevolazioni fiscali per chi rientra."},{q:"What do many observers think of the incentives?",o:["They are only a palliative","They solved the problem","They are too generous","They should be abolished immediately"],w:"Gli incentivi resteranno un palliativo."}]},
{t:"Climate and the Alps",text:"I ghiacciai alpini si stanno ritirando a una velocità senza precedenti. Secondo i glaciologi, la Marmolada, il ghiacciaio più grande delle Dolomiti, potrebbe scomparire entro pochi decenni. Le conseguenze non riguardano solo il paesaggio: i ghiacciai sono una riserva d'acqua fondamentale per l'agricoltura e la produzione di energia idroelettrica nella Pianura Padana. Alcune località sciistiche stanno già ripensando il proprio modello economico, puntando su un turismo 'quattro stagioni' basato su escursionismo, cultura ed enogastronomia.",
q:[{q:"What is happening to Alpine glaciers?",o:["They are retreating at unprecedented speed","They are growing","They are stable","They have already disappeared"],w:"Si stanno ritirando a una velocità senza precedenti."},{q:"Why are glaciers important beyond the landscape?",o:["They are a key water reserve","They attract only skiers","They protect cities from wind","They produce oil"],w:"Una riserva d'acqua fondamentale."},{q:"Which area depends on them for agriculture and energy?",o:["The Po Valley","Sicily","Rome","Sardinia"],w:"Nella Pianura Padana."},{q:"How are some ski resorts responding?",o:["With year-round tourism","By building more ski lifts","By closing permanently","By making artificial glaciers"],w:"Un turismo 'quattro stagioni'."}]},
{t:"Made in Italy",text:"Il marchio 'Made in Italy' è sinonimo nel mondo di qualità, creatività e artigianalità, in particolare nei settori della moda, del design, dell'arredamento e dell'alimentare. Paradossalmente, però, il successo del marchio ha favorito anche la contraffazione: si stima che il cosiddetto 'Italian sounding' — prodotti che evocano l'Italia con nomi e colori ma che non sono italiani — valga decine di miliardi di euro all'anno. Per difendersi, i consorzi di tutela investono in certificazioni come DOP e IGP e in campagne di sensibilizzazione rivolte ai consumatori stranieri.",
q:[{q:"What does 'Made in Italy' represent worldwide?",o:["Quality, creativity and craftsmanship","Low prices","Mass production","Only food"],w:"Sinonimo di qualità, creatività e artigianalità."},{q:"What is 'Italian sounding'?",o:["Products that evoke Italy but aren't Italian","Italian music abroad","Products sold only in Italy","A language course"],w:"Prodotti che evocano l'Italia ma che non sono italiani."},{q:"What paradox does the text describe?",o:["The brand's success encouraged counterfeiting","Italian products are unpopular in Italy","Quality reduces sales","Exports are falling"],w:"Il successo del marchio ha favorito anche la contraffazione."},{q:"How do protection consortia respond?",o:["Certifications and awareness campaigns","Lower prices","Closing factories","Banning exports"],w:"Certificazioni come DOP e IGP e campagne di sensibilizzazione."}]},
{t:"Reading habits",text:"Secondo i dati più recenti, meno della metà degli italiani legge almeno un libro all'anno, una percentuale inferiore alla media europea. Il divario è marcato tra Nord e Sud e tra uomini e donne: le donne leggono sensibilmente di più. Gli editori, tuttavia, notano segnali incoraggianti: crescono i lettori giovani, spesso grazie ai social network, dove i consigli di lettura diventano virali, e aumentano le vendite di audiolibri. Resta il fatto che, in un Paese con una tradizione letteraria così ricca, la scarsa abitudine alla lettura rappresenta un paradosso culturale.",
q:[{q:"How many Italians read at least one book a year?",o:["Less than half","More than 80%","Almost all","About a quarter exactly"],w:"Meno della metà degli italiani."},{q:"Who reads more, according to the data?",o:["Women","Men","People in the South","Older men"],w:"Le donne leggono sensibilmente di più."},{q:"What encouraging sign do publishers see?",o:["More young readers thanks to social media","Fewer audiobooks","More libraries closing","Higher book prices"],w:"Crescono i lettori giovani, spesso grazie ai social network."},{q:"Why is the situation called a cultural paradox?",o:["Italy has a rich literary tradition but people read little","Italians write more than they read","Books are free","Young people don't use social media"],w:"Un Paese con una tradizione letteraria così ricca."}]},
{t:"Renovating the Colosseum",text:"Negli ultimi anni il Colosseo è stato oggetto di un importante restauro, finanziato in gran parte da un'azienda privata italiana del settore calzaturiero. L'operazione, inizialmente criticata da chi temeva una 'privatizzazione' dei beni culturali, è stata poi considerata un modello di collaborazione tra pubblico e privato. I lavori hanno restituito alla facciata il colore originale del travertino, oscurato da secoli di smog. Oggi si discute della ricostruzione dell'arena, che permetterebbe ai visitatori di vedere il monumento dalla prospettiva dei gladiatori.",
q:[{q:"Who mainly financed the restoration?",o:["A private Italian footwear company","The European Union","The Vatican","Foreign tourists"],w:"Un'azienda privata italiana del settore calzaturiero."},{q:"What did critics initially fear?",o:["A 'privatisation' of cultural heritage","Damage to the stones","Higher ticket prices only","Closure of the monument"],w:"Una 'privatizzazione' dei beni culturali."},{q:"What did the works achieve?",o:["Restored the original colour of the travertine","Built a new roof","Added a museum","Removed the arena"],w:"Restituito alla facciata il colore originale del travertino."},{q:"What is being discussed now?",o:["Rebuilding the arena floor","Closing the Colosseum","Moving the monument","Painting the walls"],w:"La ricostruzione dell'arena."}]},
{t:"Italian dialects today",text:"Fino agli anni Cinquanta la maggior parte degli italiani parlava in famiglia il dialetto, e l'italiano era per molti una lingua quasi straniera. La televisione, la scuola obbligatoria e le migrazioni interne hanno favorito la diffusione dell'italiano standard. Oggi quasi tutti parlano italiano, ma i dialetti non sono scomparsi: sopravvivono soprattutto in contesti informali, nella musica e nel teatro, e in alcune regioni, come il Veneto e la Campania, sono ancora molto vitali. Alcuni linguisti sottolineano che i dialetti non sono 'italiano sbagliato', ma lingue con una propria storia.",
q:[{q:"What was the situation until the 1950s?",o:["Most people spoke dialect at home","Everyone spoke standard Italian","Dialects were forbidden","People spoke English"],w:"La maggior parte degli italiani parlava in famiglia il dialetto."},{q:"Which factor spread standard Italian?",o:["Television","The internet","Tourism","Foreign films"],w:"La televisione, la scuola obbligatoria e le migrazioni interne."},{q:"Where are dialects still very much alive?",o:["Veneto and Campania","Only in Rome","Nowhere","Only in Milan"],w:"Come il Veneto e la Campania."},{q:"According to some linguists, dialects are:",o:["languages with their own history","incorrect Italian","recent inventions","only spoken by the elderly"],w:"Non sono 'italiano sbagliato', ma lingue con una propria storia."}]},
{t:"The four-day week",text:"Alcune grandi aziende italiane hanno avviato una sperimentazione della settimana lavorativa di quattro giorni, a parità di stipendio. I primi risultati sembrano positivi: la produttività non è diminuita, mentre si sono ridotte le assenze per malattia e lo stress dichiarato dai dipendenti. I sindacati accolgono con favore l'iniziativa, ma avvertono che il modello non è facilmente applicabile ai settori in cui è necessaria una presenza continua, come la sanità o il commercio. Il dibattito, insomma, è appena cominciato.",
q:[{q:"What are some companies experimenting with?",o:["A four-day week with the same salary","Longer days with more pay","Working only from home","Unpaid holidays"],w:"Settimana di quattro giorni, a parità di stipendio."},{q:"What happened to productivity?",o:["It didn't decrease","It fell sharply","It doubled","It's unknown"],w:"La produttività non è diminuita."},{q:"What did unions point out?",o:["It's hard to apply in sectors needing continuous presence","It should be compulsory","Salaries must be cut","It's illegal"],w:"Non è facilmente applicabile ai settori in cui è necessaria una presenza continua."},{q:"Which sectors are given as examples?",o:["Healthcare and retail","Banking and IT","Fashion and design","Agriculture and fishing"],w:"Come la sanità o il commercio."}]},
{t:"A film review",text:"Con il suo ultimo film, il regista racconta la storia di una famiglia napoletana negli anni Settanta attraverso gli occhi di un bambino. La fotografia è splendida e la colonna sonora, che alterna canzoni d'epoca e musica originale, accompagna con delicatezza le emozioni dei personaggi. Il punto debole è la seconda parte, che si dilunga in scene superflue e perde il ritmo iniziale. Nonostante ciò, l'interpretazione del giovane protagonista, alla sua prima esperienza davanti alla macchina da presa, vale da sola il prezzo del biglietto.",
q:[{q:"Through whose eyes is the story told?",o:["A child's","A grandmother's","A journalist's","A tourist's"],w:"Attraverso gli occhi di un bambino."},{q:"What does the reviewer praise?",o:["The photography and the soundtrack","The second half","The length","The special effects"],w:"La fotografia è splendida e la colonna sonora…"},{q:"What is the film's weak point?",o:["The second part drags","The acting","The music","The setting"],w:"La seconda parte si dilunga in scene superflue."},{q:"What does the reviewer say about the young lead actor?",o:["His performance alone is worth the ticket","He is a famous star","He should not have been cast","He only appears briefly"],w:"Vale da sola il prezzo del biglietto."}]},
{t:"Agritourism",text:"Nato negli anni Ottanta per integrare il reddito degli agricoltori, l'agriturismo è diventato una delle forme di ospitalità più apprezzate in Italia. Per legge, l'attività agricola deve restare prevalente rispetto a quella turistica, e almeno una parte dei prodotti serviti deve provenire dall'azienda stessa o dal territorio. Questo garantisce un'esperienza autentica, ma comporta anche dei limiti: molti agriturismi non possono offrire i servizi di un albergo, come la reception aperta tutto il giorno. Per molti ospiti, però, proprio questa semplicità è il valore aggiunto.",
q:[{q:"Why was agritourism created?",o:["To supplement farmers' income","To replace hotels","To attract foreign investors","To build new villages"],w:"Per integrare il reddito degli agricoltori."},{q:"What does the law require?",o:["Farming must remain the main activity","Guests must work on the farm","Only foreign guests are allowed","Swimming pools are compulsory"],w:"L'attività agricola deve restare prevalente."},{q:"Where must some of the food come from?",o:["The farm itself or the local area","Supermarkets","Abroad","The city"],w:"Dall'azienda stessa o dal territorio."},{q:"What do many guests see as the added value?",o:["The simplicity","The 24-hour reception","The luxury","The low prices"],w:"Proprio questa semplicità è il valore aggiunto."}]},
{t:"Fake news",text:"Secondo un'indagine recente, oltre la metà degli italiani si informa principalmente attraverso i social network, dove le notizie false circolano più velocemente di quelle vere. Gli esperti suggeriscono alcune semplici regole: verificare la fonte, diffidare dei titoli sensazionalistici, controllare la data della notizia e confrontare più testate prima di condividere un contenuto. Alcune scuole hanno introdotto corsi di 'educazione digitale', convinte che il pensiero critico sia oggi una competenza fondamentale quanto saper leggere e scrivere.",
q:[{q:"How do over half of Italians mainly get information?",o:["Through social networks","Through newspapers","Through TV only","Through radio"],w:"Principalmente attraverso i social network."},{q:"Which rule do experts suggest?",o:["Check the source","Share quickly","Trust sensational headlines","Ignore dates"],w:"Verificare la fonte."},{q:"Why compare several outlets?",o:["To verify information before sharing","To find the funniest version","To read faster","To avoid paying"],w:"Confrontare più testate prima di condividere."},{q:"What do some schools believe?",o:["Critical thinking is as essential as reading and writing","Social media should be banned","Students should not use phones","Digital education is useless"],w:"Il pensiero critico sia una competenza fondamentale quanto saper leggere e scrivere."}]},
{t:"Population decline",text:"L'Italia è uno dei Paesi con il tasso di natalità più basso d'Europa: nascono sempre meno bambini, mentre la popolazione invecchia rapidamente. Le cause sono molteplici: la precarietà del lavoro giovanile, il costo degli affitti, la scarsità di servizi per l'infanzia e la difficoltà, soprattutto per le donne, di conciliare carriera e famiglia. Gli economisti avvertono che, senza un'inversione di tendenza, il sistema pensionistico e quello sanitario potrebbero diventare insostenibili. Alcuni propongono di puntare anche su politiche di integrazione dei migranti.",
q:[{q:"What is said about Italy's birth rate?",o:["It's among the lowest in Europe","It's the highest in Europe","It's increasing fast","It's stable"],w:"Il tasso di natalità più basso d'Europa."},{q:"Which cause is mentioned?",o:["Job insecurity among young people","Too many nurseries","Low rents","Generous salaries"],w:"La precarietà del lavoro giovanile."},{q:"What do economists warn about?",o:["Pensions and healthcare may become unsustainable","Schools will be overcrowded","Housing will be too cheap","Tourism will fall"],w:"Il sistema pensionistico e quello sanitario potrebbero diventare insostenibili."},{q:"What do some propose as part of the solution?",o:["Migrant integration policies","Closing borders","Raising the retirement age to 80","Reducing healthcare"],w:"Politiche di integrazione dei migranti."}]},
{t:"Street food in Palermo",text:"Palermo è considerata una delle capitali mondiali dello street food. Nei mercati storici come Ballarò e la Vucciria si possono assaggiare arancine, panelle, sfincione e il celebre pane con la milza, accompagnati dalle 'abbanniate', le grida con cui i venditori richiamano i clienti in dialetto. Molti di questi piatti nascono come cibo povero, preparato con ingredienti economici, e raccontano secoli di dominazioni straniere: araba, normanna, spagnola. Mangiare per strada a Palermo, insomma, è anche un modo per leggere la storia della città.",
q:[{q:"What is Palermo considered?",o:["One of the world capitals of street food","The capital of Italian fashion","A city without markets","The home of pizza"],w:"Una delle capitali mondiali dello street food."},{q:"What are the 'abbanniate'?",o:["Vendors' shouts calling customers","Typical desserts","Market stalls","Street musicians"],w:"Le grida con cui i venditori richiamano i clienti."},{q:"How did many of these dishes originate?",o:["As poor people's food","As royal dishes","As modern fusion recipes","As tourist inventions"],w:"Nascono come cibo povero."},{q:"What do the dishes reflect, according to the text?",o:["Centuries of foreign dominations","Modern American influence","Only Greek culture","Northern Italian cuisine"],w:"Secoli di dominazioni straniere: araba, normanna, spagnola."}]},
{t:"Sustainable fashion",text:"Il settore della moda è tra i più inquinanti al mondo, e anche l'Italia, patria di grandi marchi, sta facendo i conti con questa realtà. Negli ultimi anni sono nati numerosi progetti di moda sostenibile: tessuti ricavati da scarti agricoli, come le bucce d'arancia o le fibre di ortica, laboratori che riparano invece di sostituire, piattaforme per la compravendita di abiti usati. I consumatori più giovani sembrano particolarmente sensibili al tema, anche se il prezzo più alto dei capi sostenibili resta un ostacolo per molti.",
q:[{q:"What is said about the fashion industry?",o:["It's among the most polluting","It's the cleanest industry","It doesn't exist in Italy","It's shrinking fast"],w:"Tra i più inquinanti al mondo."},{q:"Which innovative material is mentioned?",o:["Fabric from orange peel","Recycled glass","Plastic from bottles only","Synthetic silk"],w:"Tessuti ricavati da scarti agricoli, come le bucce d'arancia."},{q:"What do some workshops do?",o:["Repair instead of replacing","Produce cheaper clothes","Import fabrics","Sell only luxury items"],w:"Laboratori che riparano invece di sostituire."},{q:"What obstacle remains for many consumers?",o:["The higher price of sustainable clothes","Lack of interest","Poor quality","No shops in Italy"],w:"Il prezzo più alto dei capi sostenibili resta un ostacolo."}]}
],
C1: [
{t:"The value of slowness",text:"Viviamo in un'epoca che celebra la velocità come una virtù in sé: rispondere subito, consumare in fretta, ottimizzare ogni minuto. Eppure, a ben vedere, molte delle esperienze che consideriamo più significative richiedono tempo: imparare una lingua, coltivare un'amicizia, comprendere un'opera d'arte. Non si tratta di demonizzare la tecnologia, che ha reso possibili conquiste impensabili, bensì di riconoscere che la lentezza non è sinonimo di inefficienza. Al contrario, essa costituisce talvolta la condizione stessa della profondità. In questo senso, la 'filosofia slow', nata in ambito gastronomico, si è estesa a campi diversissimi, dall'urbanistica all'educazione, proponendo un diverso rapporto con il tempo.",
q:[{q:"What is the author's main argument?",o:["Slowness can be a condition for depth","Technology should be rejected","Speed is always a virtue","Slow food is the only valid philosophy"],w:"La lentezza… costituisce talvolta la condizione stessa della profondità."},{q:"What is the author's attitude towards technology?",o:["Not hostile: it has enabled great achievements","Completely negative","Indifferent","Enthusiastic about speed"],w:"Non si tratta di demonizzare la tecnologia."},{q:"'Bensì' in the text introduces:",o:["a correction: but rather","a consequence","a concession","an example"],w:"Bensì = but rather, after a negation."},{q:"Where did the 'slow' philosophy originate?",o:["In gastronomy","In urban planning","In education","In technology"],w:"Nata in ambito gastronomico."}]},
{t:"Calvino's cities",text:"In 'Le città invisibili' (1972), Italo Calvino immagina un dialogo tra Marco Polo e l'imperatore Kublai Khan, al quale il viaggiatore veneziano descrive città meravigliose e impossibili. Ogni città è una metafora: c'è quella costruita sulla memoria, quella fatta di desideri, quella sospesa su una rete. Solo verso la fine il lettore intuisce che, in qualche modo, Marco Polo ha sempre parlato di Venezia. Il libro, privo di una trama tradizionale, è stato letto come una riflessione sulla città moderna, sul linguaggio e sui limiti della conoscenza, e continua a ispirare architetti e urbanisti di tutto il mondo.",
q:[{q:"Who are the characters in the dialogue?",o:["Marco Polo and Kublai Khan","Calvino and a Venetian architect","Dante and Virgil","Two emperors"],w:"Un dialogo tra Marco Polo e l'imperatore Kublai Khan."},{q:"What does the reader realise towards the end?",o:["Marco Polo has always been talking about Venice","The cities are real places in China","Kublai Khan invented the cities","Calvino was born in Venice"],w:"Marco Polo ha sempre parlato di Venezia."},{q:"How is the book's structure described?",o:["It has no traditional plot","It is a classic adventure novel","It is a historical essay","It is a travel guide"],w:"Privo di una trama tradizionale."},{q:"Who is still inspired by the book?",o:["Architects and urban planners","Only literary critics","Politicians","Tour operators"],w:"Continua a ispirare architetti e urbanisti."}]},
{t:"Artificial intelligence and translation",text:"L'avvento dei sistemi di traduzione automatica basati sull'intelligenza artificiale ha suscitato reazioni contrastanti tra i professionisti del settore. Da un lato, questi strumenti consentono di tradurre in pochi secondi testi tecnici e ripetitivi con una qualità impensabile fino a pochi anni fa; dall'altro, mostrano ancora limiti evidenti nella resa delle sfumature, dell'ironia e dei riferimenti culturali. Ne consegue che il ruolo del traduttore non sembra destinato a scomparire, quanto piuttosto a trasformarsi: sempre meno esecutore, sempre più revisore e mediatore culturale. Resta aperta, tuttavia, la questione della retribuzione, che rischia di ridursi drasticamente.",
q:[{q:"How have professionals reacted to AI translation?",o:["With mixed reactions","With total enthusiasm","With complete rejection","With indifference"],w:"Reazioni contrastanti."},{q:"Where do these systems still show limits?",o:["Nuance, irony and cultural references","Technical texts","Speed","Repetitive texts"],w:"Limiti nella resa delle sfumature, dell'ironia e dei riferimenti culturali."},{q:"How is the translator's role expected to change?",o:["Becoming more of a reviser and cultural mediator","Disappearing completely","Becoming more technical","Becoming better paid"],w:"Sempre più revisore e mediatore culturale."},{q:"Which issue remains open?",o:["Pay, which risks falling sharply","The quality of AI","The number of languages","Copyright of dictionaries"],w:"La questione della retribuzione."}]},
{t:"The Italian 'questione meridionale'",text:"Con l'espressione 'questione meridionale' si indica, fin dall'Unità d'Italia, il persistente divario economico e sociale tra il Nord e il Mezzogiorno. Le interpretazioni sono state molteplici: alcuni storici hanno insistito sulle politiche post-unitarie, che avrebbero favorito l'industrializzazione del Nord a scapito del Sud; altri hanno sottolineato fattori strutturali, come la scarsità di infrastrutture e la debolezza delle istituzioni locali. Gli interventi straordinari del secondo dopoguerra hanno prodotto risultati alterni. Oggi, pur in presenza di eccellenze imprenditoriali e universitarie, il Mezzogiorno continua a registrare tassi di disoccupazione giovanile ben superiori alla media nazionale.",
q:[{q:"What does 'questione meridionale' refer to?",o:["The economic and social gap between North and South","A dispute about borders","A linguistic debate","A religious controversy"],w:"Il persistente divario economico e sociale tra il Nord e il Mezzogiorno."},{q:"What did some historians emphasise?",o:["Post-unification policies favouring the North","Climate differences only","Foreign invasions in the 20th century","The role of tourism"],w:"Le politiche post-unitarie, che avrebbero favorito l'industrializzazione del Nord."},{q:"How are post-war interventions judged?",o:["As having mixed results","As a complete success","As a total failure","As never implemented"],w:"Hanno prodotto risultati alterni."},{q:"What problem persists today?",o:["Youth unemployment well above the national average","A lack of universities","Overpopulation","Excessive industrialisation"],w:"Tassi di disoccupazione giovanile ben superiori alla media nazionale."}]},
{t:"Bureaucracy reform",text:"La semplificazione amministrativa è da decenni al centro delle promesse di ogni governo. Tuttavia, nonostante la digitalizzazione di numerosi servizi — dalla carta d'identità elettronica allo SPID — molti cittadini continuano a percepire la pubblica amministrazione come lenta e farraginosa. Secondo alcuni giuristi, il problema non risiede tanto nella mancanza di strumenti tecnologici, quanto nella stratificazione normativa: leggi che si sovrappongono, competenze frammentate tra enti diversi, un linguaggio spesso incomprensibile. Digitalizzare procedure complesse senza ripensarle, osservano, significa soltanto rendere più veloce la complessità.",
q:[{q:"What has every government promised for decades?",o:["Administrative simplification","Higher taxes","New ministries","More paperwork"],w:"La semplificazione amministrativa."},{q:"How do many citizens still see public administration?",o:["Slow and cumbersome","Fast and efficient","Fully digital","Too lenient"],w:"Lenta e farraginosa."},{q:"According to some jurists, the real problem is:",o:["the layering of laws and fragmented responsibilities","the lack of computers","too few employees","excessive transparency"],w:"La stratificazione normativa…"},{q:"What does 'rendere più veloce la complessità' imply?",o:["Digitising without rethinking procedures doesn't solve the problem","Speed solves everything","Complexity is desirable","Technology should be avoided"],w:"Digitalizzare senza ripensare non basta."}]},
{t:"The Renaissance workshop",text:"Nella Firenze del Quattrocento l'arte non era il frutto del genio solitario, come vorrebbe un'immagine romantica successiva, bensì il prodotto di un sistema organizzato: la bottega. Qui il maestro dirigeva un gruppo di garzoni e apprendisti, che imparavano il mestiere macinando i colori, preparando le tavole e, col tempo, dipingendo intere parti delle opere. Leonardo da Vinci, ad esempio, si formò nella bottega del Verrocchio, dove — secondo la tradizione — avrebbe dipinto l'angelo nel 'Battesimo di Cristo' con una tale maestria che il maestro decise di abbandonare la pittura. L'aneddoto, probabilmente leggendario, rivela comunque quanto fosse fluida la frontiera tra maestro e allievo.",
q:[{q:"What does the text say about Renaissance art?",o:["It was produced by an organised workshop system","It was the work of solitary geniuses","It was funded by the state","It was mostly sculpture"],w:"Il prodotto di un sistema organizzato: la bottega."},{q:"What did apprentices do?",o:["Ground colours, prepared panels and later painted parts of works","Only cleaned the workshop","Sold the paintings","Wrote contracts"],w:"Macinando i colori, preparando le tavole e… dipingendo intere parti."},{q:"Where did Leonardo train?",o:["In Verrocchio's workshop","In Michelangelo's studio","In Rome","On his own"],w:"Nella bottega del Verrocchio."},{q:"How does the author regard the anecdote about the angel?",o:["Probably legendary, but revealing","Historically proven","Completely irrelevant","Invented by Leonardo"],w:"L'aneddoto, probabilmente leggendario, rivela comunque…"}]},
{t:"Water management",text:"Paradossalmente, l'Italia è uno dei Paesi europei più ricchi d'acqua e, al tempo stesso, uno di quelli che ne sprecano di più. Si stima che oltre un terzo dell'acqua immessa nella rete idrica vada perso a causa di tubature vecchie e manutenzione insufficiente. Le estati sempre più siccitose hanno reso il problema urgente: in alcune regioni è stato necessario razionare l'acqua, con gravi danni per l'agricoltura. Gli esperti concordano sul fatto che servano investimenti massicci nelle infrastrutture, ma ricordano anche il ruolo dei comportamenti individuali, a partire dal consumo domestico, tra i più alti d'Europa.",
q:[{q:"What paradox does the text describe?",o:["Italy is rich in water but wastes a lot","Italy has no water but uses little","Italy imports all its water","Italy has too many reservoirs"],w:"Ricchi d'acqua e… uno di quelli che ne sprecano di più."},{q:"How much water is lost in the network?",o:["Over a third","About 5%","Almost all","Half exactly"],w:"Oltre un terzo dell'acqua."},{q:"Why has the problem become urgent?",o:["Increasingly dry summers","Population growth","New factories","Tourism in winter"],w:"Le estati sempre più siccitose."},{q:"Besides infrastructure, what do experts mention?",o:["Individual behaviour, starting with household use","Banning agriculture","Importing water","Building desalination plants only"],w:"Il ruolo dei comportamenti individuali."}]},
{t:"Italian cinema",text:"Il neorealismo, sviluppatosi nell'immediato dopoguerra con registi come Rossellini e De Sica, rivoluzionò il linguaggio cinematografico: riprese in esterni, attori non professionisti e storie di gente comune raccontavano un Paese ferito dalla guerra. Negli anni Sessanta Fellini e Antonioni avrebbero portato il cinema italiano verso territori più personali e visionari, mentre la commedia all'italiana avrebbe ritratto, con ironia amara, le contraddizioni del boom economico. Non è un caso che molti critici considerino quel ventennio l'età d'oro del cinema italiano, la cui influenza si avverte ancora nel cinema internazionale contemporaneo.",
q:[{q:"Which feature characterised neorealism?",o:["Non-professional actors and outdoor shooting","Big studio sets","Science fiction stories","Famous Hollywood stars"],w:"Riprese in esterni, attori non professionisti."},{q:"What did the commedia all'italiana portray?",o:["The contradictions of the economic boom","Ancient Rome","Fairy tales","War battles"],w:"Le contraddizioni del boom economico."},{q:"Which directors took cinema in a more personal, visionary direction?",o:["Fellini and Antonioni","Rossellini and De Sica","Calvino and Eco","Verdi and Puccini"],w:"Fellini e Antonioni."},{q:"What do many critics consider that period?",o:["The golden age of Italian cinema","A period of decline","A purely commercial phase","Unimportant internationally"],w:"L'età d'oro del cinema italiano."}]},
{t:"Remote villages",text:"Sono migliaia i piccoli comuni italiani, soprattutto nelle aree interne dell'Appennino, minacciati dallo spopolamento. Per invertire la tendenza, alcune amministrazioni hanno lanciato iniziative audaci: case vendute al prezzo simbolico di un euro, a condizione che l'acquirente si impegni a ristrutturarle entro pochi anni; incentivi per chi apre un'attività; connessioni a banda larga per attrarre lavoratori da remoto. I risultati sono eterogenei: in alcuni casi il progetto ha portato nuovi residenti e turismo, in altri si è rivelato poco più di un'operazione mediatica, priva dei servizi essenziali — scuole, trasporti, presidi sanitari — senza i quali nessuno sceglie davvero di trasferirsi.",
q:[{q:"What threatens many small towns?",o:["Depopulation","Overtourism","Pollution","Floods"],w:"Minacciati dallo spopolamento."},{q:"What condition comes with one-euro houses?",o:["The buyer must renovate within a few years","The buyer must be Italian","The buyer must open a shop","The buyer must live there forever"],w:"A condizione che l'acquirente si impegni a ristrutturarle."},{q:"Why is broadband mentioned?",o:["To attract remote workers","To help tourists find hotels","To sell houses online","To connect schools only"],w:"Per attrarre lavoratori da remoto."},{q:"Why have some projects failed, according to the text?",o:["Essential services were missing","Houses were too expensive","There was too much interest","The media ignored them"],w:"Priva dei servizi essenziali… senza i quali nessuno sceglie di trasferirsi."}]},
{t:"The language of politics",text:"Negli ultimi decenni il linguaggio politico italiano ha subito una trasformazione profonda. Se un tempo i leader si esprimevano con un registro elevato, ricco di subordinate e di riferimenti colti — il cosiddetto 'politichese' — oggi prevale uno stile diretto, colloquiale, spesso aggressivo, modellato sui tempi dei social network. Alcuni linguisti vedono in questo cambiamento una forma di avvicinamento ai cittadini; altri vi leggono un impoverimento del dibattito pubblico, ridotto a slogan e semplificazioni. Ciò che pare innegabile è che la forma del discorso non sia neutra: il modo in cui si parla di un problema contribuisce a definire il problema stesso.",
q:[{q:"What was 'politichese'?",o:["A high, complex political register","Social media slang","A regional dialect","A type of slogan"],w:"Un registro elevato, ricco di subordinate e di riferimenti colti."},{q:"What characterises today's political language?",o:["A direct, colloquial, often aggressive style","Very long speeches","Latin quotations","Total silence on social media"],w:"Uno stile diretto, colloquiale, spesso aggressivo."},{q:"How do some linguists interpret the change positively?",o:["As bringing politics closer to citizens","As making debate richer","As more elegant","As more traditional"],w:"Una forma di avvicinamento ai cittadini."},{q:"What does the author consider undeniable?",o:["The way we speak about a problem helps define it","Slogans are always effective","Language has no influence","Old politicians spoke better"],w:"La forma del discorso non è neutra."}]},
{t:"Elena Ferrante",text:"Il caso Elena Ferrante rappresenta un unicum nel panorama letterario contemporaneo. L'autrice della tetralogia 'L'amica geniale', tradotta in decine di lingue e adattata per la televisione, ha scelto fin dall'esordio di restare anonima, sostenendo che i libri, una volta scritti, non abbiano bisogno dei loro autori. Questa scelta ha alimentato curiosità e speculazioni, culminate in tentativi giornalistici di svelarne l'identità, ampiamente criticati come violazioni della privacy. Al di là del mistero, i romanzi hanno conquistato i lettori grazie al ritratto intenso di un'amicizia femminile sullo sfondo di una Napoli povera e violenta, attraversata dai mutamenti del secondo Novecento.",
q:[{q:"What is unique about Elena Ferrante?",o:["She has chosen to remain anonymous","She writes only in English","She has never been translated","She is a journalist"],w:"Ha scelto fin dall'esordio di restare anonima."},{q:"What is her justification?",o:["Books, once written, don't need their authors","She dislikes publicity tours","Her family asked her","Her publisher imposed it"],w:"I libri, una volta scritti, non abbiano bisogno dei loro autori."},{q:"How were attempts to reveal her identity viewed?",o:["Widely criticised as privacy violations","Celebrated as great journalism","Ignored","Approved by her"],w:"Ampiamente criticati come violazioni della privacy."},{q:"What is the central theme of the tetralogy?",o:["A female friendship in a poor, violent Naples","A love story in Milan","A crime investigation in Rome","A family saga in Sicily"],w:"Un'amicizia femminile sullo sfondo di una Napoli povera e violenta."}]},
{t:"Heritage and tourism",text:"L'Italia detiene il maggior numero di siti iscritti nella Lista del Patrimonio Mondiale dell'UNESCO, un primato che costituisce al tempo stesso una risorsa e una responsabilità. La tutela di un patrimonio così vasto richiede risorse ingenti, spesso insufficienti, mentre la valorizzazione turistica, se mal gestita, rischia di compromettere proprio ciò che intende promuovere. Il dibattito oscilla tra chi auspica una gestione più manageriale dei musei, con maggiore autonomia e attenzione ai ricavi, e chi teme una 'mercificazione' della cultura. Forse la sfida consiste nel conciliare accessibilità e conservazione, nella consapevolezza che il patrimonio non appartiene soltanto a chi lo visita oggi, ma anche alle generazioni future.",
q:[{q:"What record does Italy hold?",o:["The highest number of UNESCO World Heritage sites","The most visited museum","The oldest university","The largest library"],w:"Il maggior numero di siti iscritti nella Lista del Patrimonio Mondiale."},{q:"What risk does poorly managed tourism pose?",o:["Compromising what it aims to promote","Reducing ticket prices","Closing museums","Increasing funding"],w:"Rischia di compromettere proprio ciò che intende promuovere."},{q:"What do opponents of a 'managerial' approach fear?",o:["The commodification of culture","Too few visitors","Better conservation","Lower salaries"],w:"Una 'mercificazione' della cultura."},{q:"According to the author, heritage belongs:",o:["also to future generations","only to the state","only to tourists","to private companies"],w:"Non appartiene soltanto a chi lo visita oggi, ma anche alle generazioni future."}]},
{t:"Gestures",text:"Che gli italiani parlino con le mani è uno degli stereotipi più diffusi, ma, come molti stereotipi, contiene un fondo di verità. I gesti italiani costituiscono un vero e proprio repertorio comunicativo, con significati condivisi e talvolta molto precisi: la mano a borsa, con le dita unite verso l'alto, esprime perplessità o insofferenza ('ma cosa vuoi?'); il dito che tira giù la palpebra invita a stare attenti. Alcuni antropologi ipotizzano che questa ricchezza gestuale si sia sviluppata in secoli di frammentazione linguistica, quando i gesti aiutavano a capirsi tra parlanti di dialetti diversi. Altri la collegano semplicemente a una cultura della piazza, in cui la comunicazione è teatrale e pubblica.",
q:[{q:"How does the author treat the stereotype?",o:["It contains some truth","It is completely false","It is offensive and wrong","It only applies to the South"],w:"Contiene un fondo di verità."},{q:"What does the 'mano a borsa' gesture express?",o:["Perplexity or impatience","Agreement","Hunger","Love"],w:"Esprime perplessità o insofferenza."},{q:"What is one hypothesis for the origin of gestures?",o:["Centuries of linguistic fragmentation","Influence of television","Lack of education","Foreign invasions in the 20th century"],w:"Secoli di frammentazione linguistica."},{q:"What does 'cultura della piazza' suggest?",o:["Public, theatrical communication","Private, quiet conversation","Written communication","Online chat"],w:"La comunicazione è teatrale e pubblica."}]}
]
};
